import{_ as a,o as t,c as i,ag as r}from"./chunks/framework.cyF4XceO.js";const u=JSON.parse('{"title":"0004 — Takoform is an experimental specification project","description":"","frontmatter":{},"headers":[],"relativePath":"spec/decisions/0004-takoform-is-an-experimental-specification.md","filePath":"spec/decisions/0004-takoform-is-an-experimental-specification.md"}'),o={name:"spec/decisions/0004-takoform-is-an-experimental-specification.md"};function n(s,e,l,c,d,p){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="_0004-—-takoform-is-an-experimental-specification-project" tabindex="-1">0004 — Takoform is an experimental specification project <a class="header-anchor" href="#_0004-—-takoform-is-an-experimental-specification-project" aria-label="Permalink to &quot;0004 — Takoform is an experimental specification project&quot;">​</a></h1><ul><li>Status: accepted</li><li>Date: 2026-08-04</li><li>Owners: Takoform maintainers</li><li>Supersedes: admission and graduation policy in <a href="./0001-provider-v1-keeps-form-versions-independent.html">0001</a></li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Takoform published immutable Form packages and introduced <code>standard</code> and <code>portable-standard</code> classifications before independent hosts and sustained real-world consumers had established interoperability. Package publication, provider support, one host&#39;s lifecycle evidence, and commercial availability were consequently presented as one maturity ladder. The result was excessive Form version churn, a privileged ten-Form subset, and documentation that overstated the maturity of the specification.</p><p>The published identities cannot be safely renumbered, overwritten, or erased. The project can still provide a useful portable boundary for desired-state schemas, content-addressed packages, host lifecycle interoperability, and Terraform/OpenTofu clients, but that value must be demonstrated rather than self-declared.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Takoform remains a standalone <strong>Experimental specification and tooling project</strong>. It is not currently an industry standard, certification authority, universal cloud API, or guarantee of backend portability.</p><p>Current Form work follows four lifecycle states:</p><ol><li><strong>Proposal</strong> — mutable and unversioned design material tied to a named owner, real consumer, host implementation, and prior-art analysis;</li><li><strong>Experimental</strong> — a reproducible public <code>0.x</code> FormRef whose contract may still change under the documented compatibility policy;</li><li><strong>Stable</strong> — an evidence-earned contract with independent implementation, interoperability, migration, deprecation, and operational experience;</li><li><strong>Legacy</strong> — an immutable retained identity that is no longer the basis for new specification work.</li></ol><p>The existing public FormRefs, packages, schemas, tags, provider releases, signed reports, and admission closures remain immutable legacy evidence. Their historical <code>standard</code> and <code>portable-standard</code> fields do not make a current normative approved set, and no replacement central admission generation is introduced.</p><p>Form maturity, provider compatibility, Host Support, operator activation, and Cloud availability are separate facts:</p><ul><li>the provider version describes only provider protocol, schema, state, and host-client compatibility;</li><li>a host reports support for an exact FormRef and does not grant that Form maturity;</li><li>an operator decides whether supported Forms are installed and activated;</li><li>a commercial platform publishes a Service Offering for an exact supported FormRef without changing the Form&#39;s maturity.</li></ul><p>OCCI, CIMI, TOSCA, Kubernetes/Crossplane, and established provider APIs are required prior art where relevant, not automatic compliance targets. A new Takoform abstraction must state the concrete difference and why it is needed.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>New Form designs can change freely as Proposals without consuming public versions or package identities.</li><li>New public Form lines begin at <code>0.x</code>; existing public identities never rewind or reuse an occupied version.</li><li>Stable is deliberately difficult to earn and cannot be inferred from a package, provider release, generated catalog entry, or a single host report.</li><li>Existing users retain exact read, observe, delete, recovery, revocation, and explicit migration paths for legacy Forms.</li><li>Takoform documentation must lead with experimental status, the portable boundary, known limitations, and exact host support rather than approval counts or release closure evidence.</li><li>Decisions 0001 through 0003 remain historical rationale. This decision replaces only the active admission/graduation model; provider/Form version independence and immutable public identities remain in force.</li></ul><h2 id="rejected-alternatives" tabindex="-1">Rejected alternatives <a class="header-anchor" href="#rejected-alternatives" aria-label="Permalink to &quot;Rejected alternatives&quot;">​</a></h2><ul><li><strong>Delete Takoform.</strong> Rejected because the verified schema, package, trust, lifecycle, and IaC boundary remains useful if governed by real evidence.</li><li><strong>Renumber the provider or published Forms back to <code>0.1.0</code>.</strong> Rejected because provider compatibility is independent and published identities are immutable.</li><li><strong>Keep ten approved Forms and treat the remainder as lower quality.</strong> Rejected because one admission closure reflects evidence for exact identities, not a permanent normative hierarchy.</li><li><strong>Adopt OCCI or CIMI wholesale.</strong> Rejected because they remain important prior art but do not directly supply the active implementation ecosystem or modern edge/runtime contracts Takoform needs.</li></ul>',17)])])}const h=a(o,[["render",n]]);export{u as __pageData,h as default};
